package com.example.markdowndesk;
public final class ReaderUiCheck {
 static int checks;static void yes(boolean v,String why){checks++;if(!v)throw new AssertionError(why);}static void eq(float a,float b,String why){yes(Math.abs(a-b)<.00001f,why);}
 public static void main(String[] args){
  ReaderUiHarness h=new ReaderUiHarness();ReaderUiHarness.AppearanceUi ui=h.setup();Object dialog=ui.dialog;ReaderTypography original=h.readerTypography;
  yes(ui.buttons.size()==12,"all actual controls constructed");yes(ui.readerFamilyButtons[0].selected,"default serif selected");yes(ui.readerLabels[0].text.contains("1.72"),"exact default line spacing visible");
  ui.readerFamilyButtons[1].tap();yes(h.readerTypography.family==ReaderTypography.Family.SANS&&ui.readerFamilyButtons[1].selected&&!ui.readerFamilyButtons[0].selected,"family button updates immutable selection");yes(original.family==ReaderTypography.Family.SERIF,"previous immutable style unchanged");
  ui.readerPlus[0].tap();eq(1.82f,h.readerTypography.lineHeight,"line increment");ui.readerMinus[1].tap();eq(.8f,h.readerTypography.paragraphGapEm,"gap increment");ui.readerPlus[2].tap();yes(h.readerTypography.horizontalMarginPx==32,"margin increment");ui.readerPlus[3].tap();yes(h.readerTypography.measurePx==760,"width increment");
  for(int field=0;field<4;field++){for(int n=0;n<100;n++)h.adjust(field,1,ui);if(field==0)eq(2.2f,h.readerTypography.lineHeight,"upper line clamp");if(field==1)eq(1.5f,h.readerTypography.paragraphGapEm,"upper gap clamp");if(field==2)yes(h.readerTypography.horizontalMarginPx==44,"upper margin clamp");if(field==3)yes(h.readerTypography.measurePx==960,"upper measure clamp");yes(!ui.readerPlus[field].enabled&&ui.readerMinus[field].enabled,"upper boundary availability");for(int n=0;n<100;n++)h.adjust(field,-1,ui);yes(!ui.readerMinus[field].enabled&&ui.readerPlus[field].enabled,"lower boundary availability");}
  eq(1.2f,h.readerTypography.lineHeight,"line clamps rather than fallback");eq(.5f,h.readerTypography.paragraphGapEm,"gap clamps");yes(h.readerTypography.horizontalMarginPx==12&&h.readerTypography.measurePx==480,"integer clamps");
  ui.buttons.get(ui.buttons.size()-1).tap();eq(1.72f,h.readerTypography.lineHeight,"reset exact line default");eq(.9f,h.readerTypography.paragraphGapEm,"reset gap default");yes(h.readerTypography.horizontalMarginPx==28&&h.readerTypography.measurePx==720&&h.readerTypography.family==ReaderTypography.Family.SERIF,"reset defaults");yes(ui.dialog==dialog&&h.renders==h.refreshes&&h.renders>0,"live same dialog refresh for each style change");
  h.palette.text=17;h.palette.muted=23;h.palette.accentSoft=29;h.refreshAppearance(ui);yes(ui.typographyHeading.color==17&&ui.readerLabels[0].color==23&&ui.readerFamilyButtons[0].background.equals(29),"live theme colors on existing reading controls");
  java.util.Locale previous=java.util.Locale.getDefault();try{java.util.Locale.setDefault(java.util.Locale.FRANCE);h.refreshAppearance(ui);yes(ui.readerLabels[0].text.contains("1.72"),"stable numeric value label under comma locale");}finally{java.util.Locale.setDefault(previous);}
  ReaderTypography read=h.read();eq(1.72f,read.lineHeight,"persist reload");yes(h.preferences.values.get("reader_margin_px") instanceof Integer&&h.preferences.values.get("reader_line_height") instanceof Float,"typed persisted values");
  h.preferences.values.put("reader_font_family","<script>");h.preferences.values.put("reader_line_height",Float.NaN);h.preferences.values.put("reader_paragraph_gap",1.2f);h.preferences.values.put("reader_margin_px","bad");h.preferences.values.put("reader_measure_px",960);
  read=h.read();yes(read.family==ReaderTypography.Family.SERIF,"hostile family fallback");eq(1.72f,read.lineHeight,"NaN fallback");eq(1.2f,read.paragraphGapEm,"valid unrelated field retained");yes(read.horizontalMarginPx==28&&read.measurePx==960,"wrong type independent fallback");
  for(int field=0;field<4;field++)yes(ui.readerMinus[field].description.startsWith("Decrease reading")&&ui.readerPlus[field].description.startsWith("Increase reading"),"stable named controls");
  System.out.println("Reader typography UI: "+checks+" checks PASS; actual extracted control callbacks, persistence and live labels");
 }
}
